// API-tier LLM provider config (#1085 / epic #1078) — which provider + model + key
// powers llm_complete-backed (planning / assistant) calls: the planning autopilot, the
// LLM grader, the cleanup-scan verifier. This is DISTINCT from the per-pane runtime
// model (ModelId / defaultModel / paneModels → `claude --model`), which the harness
// adapter owns (P0/P2) — do not conflate them.

import modelDefaultsEmbedded from "@data/console/model-defaults.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export type LlmProvider = "anthropic" | "openai" | "gemini" | "local" | "ollama";

/** A selectable provider for the Settings UI: id + display label + API-key placeholder. */
export interface LlmProviderOption {
  id: LlmProvider;
  label: string;
  /** The key-field placeholder (empty for local providers, which need no key). */
  keyPlaceholder: string;
}

// The model-ID defaults (+ provider list) are externalized to `@data/console/model-defaults.json`
// (#2416) — the ONE source for every model default, editable without touching code + part of the
// exportable config bundle; the config-dir copy (#2047) overlays the embedded default via
// `overlayFile`. (The per-pane tier default in the same file is consumed by the model catalog,
// `@/app/console/lib/models` — a separate surface; see the note above about not conflating them.)
const MODEL_DEFAULTS = overlayFile("console/model-defaults.json", modelDefaultsEmbedded);

export interface LlmConfig {
  provider: LlmProvider;
  model: string;
  apiKey: string;
  /** OpenAI-compatible endpoint for the `local` / `ollama` provider (ignored by hosted ones). */
  baseUrl: string;
  /** The per-agent context cap (`num_ctx`) for a local runtime, or `undefined` to use the runtime's
   *  own packaged ceiling. `0` is meaningful and distinct from `undefined`: it tells the runtime not
   *  to set `num_ctx` at all. Ignored by hosted providers, which manage their own window. */
  numCtx?: number;
}

/** The store fields `resolveLlmConfig` reads — a structural subset of the app store,
 *  so the resolver is unit-testable with a plain object. */
export interface LlmConfigSource {
  llmProvider: LlmProvider;
  llmModel: string;
  claudeApiKey: string;
  openaiKey: string;
  geminiKey: string;
  localBaseUrl: string;
  /** The per-agent context cap as typed (empty ⇒ the runtime's packaged default). See
   *  {@link parseNumCtx} for why it stays a string all the way to the parse.
   *
   *  OPTIONAL, unlike the store field it mirrors. This interface is a structural subset so the
   *  resolver can be unit-tested with a plain object, and a field added later must not invalidate
   *  every existing caller's literal — absent behaves exactly as empty does (unset). The STORE
   *  always supplies it; `LlmState` types it required. */
  llmNumCtx?: string;
}

/** Default model for a local runtime (Ollama / OpenAI-compatible). A hosted `claude-*` model can
 *  never run locally, so a local provider falls back to this. (`ollama run qwen3-coder`.) */
export const DEFAULT_LOCAL_MODEL: string = MODEL_DEFAULTS.localModel;
/** The packaged Anthropic default, restored when switching back to a hosted provider. */
export const DEFAULT_ANTHROPIC_MODEL: string = MODEL_DEFAULTS.anthropicModel;
/** The default OpenAI-compatible endpoint for the `local`/`ollama` provider (Ollama's port). */
export const DEFAULT_LOCAL_BASE_URL: string = MODEL_DEFAULTS.localBaseUrl;
/** The packaged per-agent context cap (`num_ctx`) — shown as the Settings placeholder so the UI
 *  states the real default instead of a number invented in the card (the old placeholder said
 *  `64000`, which matched nothing).
 *
 *  THE SAME VALUE IS COMPILED INTO THE RUNTIME as `DEFAULT_NUM_CTX_CAP` in `crates/llm/src/ollama.rs`,
 *  because the cap has to apply when nothing sets `$BSC_AGENT_NUM_CTX` at all. Two copies across a
 *  language boundary is a drift risk, so `default_num_ctx_cap_matches_the_packaged_default` in that
 *  crate READS THIS FILE and fails if they diverge — change one and the Rust test tells you. */
export const DEFAULT_NUM_CTX: number = MODEL_DEFAULTS.localNumCtx;
/** The selectable providers, in Settings display order. */
export const LLM_PROVIDERS: LlmProviderOption[] = MODEL_DEFAULTS.providers as LlmProviderOption[];

/** The model to actually send for a config. A `local`/`ollama` provider substitutes
 *  {@link DEFAULT_LOCAL_MODEL} when the stored model is empty or a hosted `claude-*` model (which
 *  404s on Ollama), so a stale Anthropic default never reaches the local runtime. */
export function resolveModel(provider: LlmProvider, model: string): string {
  if (providerNeedsBscAgent(provider) && (model.trim() === "" || /^claude/i.test(model))) {
    return DEFAULT_LOCAL_MODEL;
  }
  return model;
}

/** The model-field value after the user switches provider — keeps the field runnable on the new
 *  provider without clobbering a model the user explicitly typed:
 *   • → local/ollama: use {@link DEFAULT_LOCAL_MODEL} when the field is empty or a hosted `claude-*`.
 *   • → a hosted provider: restore {@link DEFAULT_ANTHROPIC_MODEL} when the field is empty or still
 *     holds the local default. Any other (custom) model is preserved as-is. */
export function modelOnProviderSwitch(provider: LlmProvider, currentModel: string): string {
  const m = currentModel.trim();
  if (providerNeedsBscAgent(provider)) {
    return m === "" || /^claude/i.test(m) ? DEFAULT_LOCAL_MODEL : currentModel;
  }
  return m === "" || m === DEFAULT_LOCAL_MODEL ? DEFAULT_ANTHROPIC_MODEL : currentModel;
}

/** The name before a `:tag` (Ollama installed names commonly carry one, e.g. `qwen3-coder:latest`;
 *  a bare configured name like `qwen3-coder` has none). */
function baseModelName(model: string): string {
  return model.split(":")[0];
}

/** Whether `model` is present in `installed` (from the `ollama_models` command) — exact match, or,
 *  when `model` carries no `:tag` of its own, matching by {@link baseModelName} so a bare
 *  `qwen3-coder` still counts as installed when Ollama only has the tagged `qwen3-coder:latest`
 *  (Ollama resolves a bare name to its `:latest` tag the same way). A model that DOES specify a
 *  tag has to match that tag exactly. Mirrors `model_is_installed` in `crates/llm/src/ollama.rs`
 *  — kept in sync by hand since the two sides can't share code (#176). */
export function isLocalModelInstalled(model: string, installed: string[]): boolean {
  if (installed.includes(model)) return true;
  return !model.includes(":") && installed.some((m) => baseModelName(m) === model);
}

/** Resolve `preferred` (typically {@link DEFAULT_LOCAL_MODEL}) against what's actually installed:
 *  the exact/base-name match when there is one, else the first installed model — always a name
 *  Ollama will actually run, never a guess. `undefined` only when `installed` is empty (nothing to
 *  pick from), which the caller reads as "leave the packaged default in place" (#176). */
export function pickInstalledLocalModel(preferred: string, installed: string[]): string | undefined {
  if (installed.length === 0) return undefined;
  const exact = installed.find((m) => m === preferred);
  if (exact) return exact;
  if (!preferred.includes(":")) {
    const sameBase = installed.find((m) => baseModelName(m) === preferred);
    if (sameBase) return sameBase;
  }
  return installed[0];
}

/** Parse the typed per-agent context cap into what the runtime should be handed.
 *
 *  Three states, and they do NOT collapse into a number:
 *   • empty / not a number ⇒ `undefined` — say nothing, let the runtime use its packaged ceiling.
 *     This is the default deliberately: raising that ceiling then reaches every install, not only
 *     the ones that never opened the field.
 *   • `"0"` ⇒ `0` — a real instruction ("don't set `num_ctx`"), not an absence.
 *   • any other non-negative integer ⇒ that ceiling.
 *
 *  A negative value is nonsense for a window size and is treated as unset rather than passed on to
 *  be clamped somewhere far from here. */
export function parseNumCtx(raw: string | undefined): number | undefined {
  const n = Number.parseInt((raw ?? "").trim(), 10);
  return Number.isFinite(n) && n >= 0 ? n : undefined;
}

/** Resolve the active provider + model and the API key for THAT provider.
 *  `local` & `ollama` (OpenAI-compatible, e.g. Ollama) need no key but carry a base URL. */
export function resolveLlmConfig(s: LlmConfigSource): LlmConfig {
  const apiKey =
    s.llmProvider === "openai" ? s.openaiKey :
    s.llmProvider === "gemini" ? s.geminiKey :
    (s.llmProvider === "local" || s.llmProvider === "ollama") ? "" :
    s.claudeApiKey;
  return {
    provider: s.llmProvider,
    model: resolveModel(s.llmProvider, s.llmModel),
    apiKey,
    baseUrl: s.localBaseUrl,
    numCtx: parseNumCtx(s.llmNumCtx),
  };
}

/** Whether the config can make a call — a key is present, or it's `local`/`ollama` (no key). */
export function hasLlmKey(cfg: LlmConfig): boolean {
  return cfg.provider === "local" || cfg.provider === "ollama" || !!cfg.apiKey;
}

/** Providers Claude Code (the `claude` CLI) cannot drive — it only ever speaks to Anthropic. A
 *  SESSION (planner / worker / director) on one of these MUST run on the `bsc-agent` harness, so
 *  picking it implies bsc-agent regardless of the fleet-harness toggle. */
export function providerNeedsBscAgent(p: LlmProvider): boolean {
  return p === "local" || p === "ollama";
}

/** The harness a session should actually launch on — the FLEET-WIDE DEFAULT, which every nearer
 *  designation (`paneProviders`, a stream's own model) already overrides in `paneHarness`.
 *
 *  THE PROVIDER DOES NOT DECIDE THIS. The two settings answer different questions and were collapsed
 *  into one:
 *
 *    · `llmProvider`  — WHICH MODEL a bsc-agent session talks to.
 *    · `fleetHarness` — WHETHER a session runs bsc-agent at all.
 *
 *  This used to return `providerNeedsBscAgent(provider) ? "bsc-agent" : fleetHarness`, so choosing a
 *  local model conscripted the planner, every studio, every network architect and every un-designated
 *  fleet pane onto `bsc-agent` — and the stored `fleetHarness` was never read. MEASURED on the live
 *  store: `llmProvider: "ollama"`, `fleetHarness: "claude"`, and exactly TWO panes designated local by
 *  hand in `paneProviders`. Every other session ran local regardless.
 *
 *  The old reasoning — "otherwise selecting Ollama would silently launch Claude Code and ignore the
 *  choice" — named a real hazard and answered it in the wrong place. Designation is already per-pane
 *  and per-stream, both AHEAD of this fallback in `paneHarness`, so making one project local never
 *  needed a global switch; and the Settings control that could have said so was DISABLED while it
 *  displayed a value it did not honour, which is worse than a control that does nothing. The answer is
 *  that the enabled control means what it says, and its hint names the provider it is not reaching.
 *
 *  `providerNeedsBscAgent` survives, because the hazard is real: it is what the Settings hint reads to
 *  warn that Claude Code cannot drive the selected provider, and what `sessionLaunch` reads to pick the
 *  MODEL for a session already on bsc-agent. It simply no longer decides the harness.
 *
 *  The parameter is KEPT (and unused) rather than removed: every caller passes the provider it already
 *  has, the signature is the documented place this question is asked, and a call site that drops the
 *  argument would be one more place to re-derive the rule if it ever changes again. */
export function effectiveHarness(
  _provider: LlmProvider,
  fleetHarness: "claude" | "bsc-agent",
): "claude" | "bsc-agent" {
  return fleetHarness;
}

/** The `BSC_AGENT_*` env a bsc-agent session needs to reach the configured LLM (#1078 P3b).
 *  The runtime reads provider/model/key (+ base URL for `local`/`ollama`) from these. */
export function bscAgentEnv(cfg: LlmConfig): Record<string, string> {
  const e: Record<string, string> = {
    BSC_AGENT_PROVIDER: cfg.provider,
    BSC_AGENT_MODEL: cfg.model,
  };
  if (cfg.apiKey) e.BSC_AGENT_API_KEY = cfg.apiKey;
  if (cfg.baseUrl) e.BSC_AGENT_BASE_URL = cfg.baseUrl;
  // The per-agent context cap. `build_provider` has honoured $BSC_AGENT_NUM_CTX since #1829, but
  // NOTHING SET IT — the Settings control was an uncontrolled placeholder input — so the one escape
  // hatch for a prompt that overflows its window existed and was unreachable.
  //
  // Explicitly `!== undefined`, never truthy: `0` MEANS "don't set num_ctx", and a truthy test would
  // silently drop exactly that instruction while looking correct.
  if (cfg.numCtx !== undefined) e.BSC_AGENT_NUM_CTX = String(cfg.numCtx);
  return e;
}

/** Map an {@link LlmConfig} to Aider's `--model` selector (#1172). Aider (via litellm) namespaces
 *  models by provider — `anthropic/…`, `gemini/…` — takes OpenAI models bare, and reaches a
 *  local / OpenAI-compatible endpoint through the `openai/…` prefix (paired with `OPENAI_API_BASE`,
 *  see {@link aiderEnv}). A model already carrying a `provider/` prefix is passed through untouched. */
export function aiderModelArg(cfg: LlmConfig): string {
  const m = cfg.model.trim();
  if (m.includes("/")) return m;
  switch (cfg.provider) {
    case "anthropic": return `anthropic/${m}`;
    case "gemini":    return `gemini/${m}`;
    case "openai":    return m;
    case "local":
    case "ollama":    return `openai/${m}`;
  }
}

/** The environment an Aider session needs to reach the configured LLM (#1172): the provider's API key
 *  under the variable Aider/litellm reads (`ANTHROPIC_API_KEY` / `OPENAI_API_KEY` / `GEMINI_API_KEY`),
 *  plus an `OPENAI_API_BASE` for a local / OpenAI-compatible endpoint. A local server needs no real
 *  key, so a placeholder satisfies the OpenAI client's non-empty check. Mirrors {@link bscAgentEnv}. */
export function aiderEnv(cfg: LlmConfig): Record<string, string> {
  const e: Record<string, string> = {};
  switch (cfg.provider) {
    case "anthropic": if (cfg.apiKey) e.ANTHROPIC_API_KEY = cfg.apiKey; break;
    case "openai":    if (cfg.apiKey) e.OPENAI_API_KEY = cfg.apiKey; break;
    case "gemini":    if (cfg.apiKey) e.GEMINI_API_KEY = cfg.apiKey; break;
    case "local":
    case "ollama":
      if (cfg.baseUrl) e.OPENAI_API_BASE = cfg.baseUrl;
      // A keyless local server still needs a non-empty OPENAI_API_KEY for the client to init.
      e.OPENAI_API_KEY = cfg.apiKey || "sk-local-none";
      break;
  }
  return e;
}

