import { describe, it, expect } from "vitest";
import {
  resolveLlmConfig, hasLlmKey, bscAgentEnv, aiderModelArg, aiderEnv, providerNeedsBscAgent, effectiveHarness,
  resolveModel, modelOnProviderSwitch, DEFAULT_LOCAL_MODEL, DEFAULT_ANTHROPIC_MODEL, DEFAULT_LOCAL_BASE_URL,
  LLM_PROVIDERS,
  type LlmConfigSource,
} from "@/shared/lib/core/llmConfig";

// #2416: the model-ID defaults + provider list moved to `@data/console/model-defaults.json` — the
// ONE source for every model default. Pin that they resolve to the previous TS-authored values.
describe("model defaults resolve from @data/console/model-defaults.json (#2416)", () => {
  it("keeps the previous packaged defaults", () => {
    expect(DEFAULT_ANTHROPIC_MODEL).toBe("claude-sonnet-4-6");
    expect(DEFAULT_LOCAL_MODEL).toBe("qwen3-coder");
    expect(DEFAULT_LOCAL_BASE_URL).toBe("http://localhost:11434/v1");
  });

  it("keeps the previous provider list + key placeholders, in order", () => {
    expect(LLM_PROVIDERS.map((p) => [p.id, p.label])).toEqual([
      ["anthropic", "Anthropic Claude"],
      ["openai",    "OpenAI"],
      ["gemini",    "Google Gemini"],
      ["local",     "Local (Ollama / OpenAI-compatible)"],
      ["ollama",    "Ollama (Local)"],
    ]);
    expect(Object.fromEntries(LLM_PROVIDERS.map((p) => [p.id, p.keyPlaceholder]))).toEqual({
      anthropic: "sk-ant-…", openai: "sk-…", gemini: "AIza…", local: "", ollama: "",
    });
  });
});

const base: LlmConfigSource = {
  llmProvider: "anthropic",
  llmModel: "claude-sonnet-4-6",
  claudeApiKey: "ant-key",
  openaiKey: "oai-key",
  geminiKey: "gem-key",
  localBaseUrl: "http://localhost:11434/v1",
};

describe("resolveLlmConfig (#1085)", () => {
  it("picks the anthropic key + model for anthropic", () => {
    expect(resolveLlmConfig(base)).toEqual({
      provider: "anthropic", model: "claude-sonnet-4-6", apiKey: "ant-key",
      baseUrl: "http://localhost:11434/v1",
    });
  });

  it("carries the configured local base URL (#1091)", () => {
    expect(resolveLlmConfig({ ...base, llmProvider: "local", localBaseUrl: "http://10.0.0.5:8080/v1" }).baseUrl)
      .toBe("http://10.0.0.5:8080/v1");
  });

  it("picks the per-provider key", () => {
    expect(resolveLlmConfig({ ...base, llmProvider: "openai" }).apiKey).toBe("oai-key");
    expect(resolveLlmConfig({ ...base, llmProvider: "gemini" }).apiKey).toBe("gem-key");
  });

  it("returns no key for local / ollama", () => {
    expect(resolveLlmConfig({ ...base, llmProvider: "local" }).apiKey).toBe("");
    expect(resolveLlmConfig({ ...base, llmProvider: "ollama" }).apiKey).toBe("");
  });

  it("carries the configured model", () => {
    expect(resolveLlmConfig({ ...base, llmProvider: "openai", llmModel: "gpt-5" }).model).toBe("gpt-5");
  });

  it("substitutes the local default when ollama still holds a stale claude model (#404 fix)", () => {
    // The bug: provider switched to ollama but llmModel left at the anthropic default → 404 on Ollama.
    expect(resolveLlmConfig({ ...base, llmProvider: "ollama" }).model).toBe(DEFAULT_LOCAL_MODEL);
    expect(resolveLlmConfig({ ...base, llmProvider: "local", llmModel: "" }).model).toBe(DEFAULT_LOCAL_MODEL);
    // A real local model the user typed is kept.
    expect(resolveLlmConfig({ ...base, llmProvider: "ollama", llmModel: "llama3.1" }).model).toBe("llama3.1");
  });
});

describe("resolveModel / modelOnProviderSwitch", () => {
  it("resolveModel swaps empty/claude models only for local providers", () => {
    expect(resolveModel("ollama", "claude-sonnet-4-6")).toBe(DEFAULT_LOCAL_MODEL);
    expect(resolveModel("local", "")).toBe(DEFAULT_LOCAL_MODEL);
    expect(resolveModel("ollama", "qwen3-coder")).toBe("qwen3-coder"); // custom kept
    expect(resolveModel("anthropic", "claude-sonnet-4-6")).toBe("claude-sonnet-4-6"); // hosted untouched
    expect(resolveModel("openai", "")).toBe(""); // hosted untouched
  });

  it("modelOnProviderSwitch defaults to qwen3-coder for ollama and restores claude for hosted", () => {
    expect(modelOnProviderSwitch("ollama", "claude-sonnet-4-6")).toBe(DEFAULT_LOCAL_MODEL);
    expect(modelOnProviderSwitch("ollama", "")).toBe(DEFAULT_LOCAL_MODEL);
    expect(modelOnProviderSwitch("ollama", "llama3.1")).toBe("llama3.1"); // custom kept
    // Switching back: a leftover local default reverts to the anthropic default.
    expect(modelOnProviderSwitch("anthropic", DEFAULT_LOCAL_MODEL)).toBe("claude-sonnet-4-6");
    expect(modelOnProviderSwitch("openai", "gpt-5")).toBe("gpt-5"); // custom kept
  });
});

describe("hasLlmKey", () => {
  it("is true when a key is present", () => {
    expect(hasLlmKey({ provider: "openai", model: "gpt-5", apiKey: "x", baseUrl: "" })).toBe(true);
  });
  it("is false when a cloud provider has no key", () => {
    expect(hasLlmKey({ provider: "anthropic", model: "m", apiKey: "", baseUrl: "" })).toBe(false);
  });
  it("is true for local / ollama even without a key", () => {
    expect(hasLlmKey({ provider: "local", model: "llama3", apiKey: "", baseUrl: "" })).toBe(true);
    expect(hasLlmKey({ provider: "ollama", model: "llama3", apiKey: "", baseUrl: "" })).toBe(true);
  });
});

describe("providerNeedsBscAgent / effectiveHarness", () => {
  it("flags local + ollama as needing bsc-agent (Claude Code can't drive them)", () => {
    expect(providerNeedsBscAgent("local")).toBe(true);
    expect(providerNeedsBscAgent("ollama")).toBe(true);
    expect(providerNeedsBscAgent("anthropic")).toBe(false);
    expect(providerNeedsBscAgent("openai")).toBe(false);
    expect(providerNeedsBscAgent("gemini")).toBe(false);
  });

  // THE RULE THIS REPLACES, and its own name said what was wrong with it: "regardless of the
  // toggle". The provider decided the harness, so designating ONE project local — which is done per
  // pane — put every studio, every network architect, the planner and every un-designated fleet pane
  // on the local model, and the stored `fleetHarness` was never read. MEASURED on the live store:
  // `llmProvider: "ollama"`, `fleetHarness: "claude"`, exactly two panes designated by hand.
  it("leaves the harness to the toggle, whatever the provider is", () => {
    expect(effectiveHarness("ollama", "claude")).toBe("claude");
    expect(effectiveHarness("local", "claude")).toBe("claude");
    expect(effectiveHarness("ollama", "bsc-agent")).toBe("bsc-agent");
    expect(effectiveHarness("anthropic", "bsc-agent")).toBe("bsc-agent");
    expect(effectiveHarness("anthropic", "claude")).toBe("claude");
  });

  // `providerNeedsBscAgent` SURVIVES, because the hazard it names is real — Claude Code only ever
  // speaks to Anthropic. It simply no longer decides the harness: the Settings hint reads it to warn
  // that the fleet is not reaching the selected provider, and `sessionLaunch` reads it to pick the
  // MODEL for a session that is already on bsc-agent.
  it("still reports which providers Claude Code cannot drive", () => {
    expect(providerNeedsBscAgent("ollama")).toBe(true);
    expect(providerNeedsBscAgent("local")).toBe(true);
    expect(providerNeedsBscAgent("anthropic")).toBe(false);
  });

  it("honors the explicit toggle for providers Claude Code can run", () => {
    expect(effectiveHarness("anthropic", "claude")).toBe("claude");
    expect(effectiveHarness("anthropic", "bsc-agent")).toBe("bsc-agent");
    expect(effectiveHarness("openai", "claude")).toBe("claude");
    expect(effectiveHarness("gemini", "bsc-agent")).toBe("bsc-agent");
  });
});

describe("bscAgentEnv", () => {
  it("always carries provider + model + key when set", () => {
    const e = bscAgentEnv({ provider: "openai", model: "gpt-5", apiKey: "k", baseUrl: "" });
    expect(e.BSC_AGENT_PROVIDER).toBe("openai");
    expect(e.BSC_AGENT_MODEL).toBe("gpt-5");
    expect(e.BSC_AGENT_API_KEY).toBe("k");
    expect(e.BSC_AGENT_BASE_URL).toBeUndefined();
  });
  it("omits the key for local (none) and carries the base URL", () => {
    const e = bscAgentEnv({ provider: "local", model: "llama3", apiKey: "", baseUrl: "http://localhost:11434/v1" });
    expect(e.BSC_AGENT_API_KEY).toBeUndefined();
    expect(e.BSC_AGENT_BASE_URL).toBe("http://localhost:11434/v1");
  });
});

describe("aiderModelArg (#1172)", () => {
  it("namespaces anthropic + gemini models by provider", () => {
    expect(aiderModelArg({ provider: "anthropic", model: "claude-sonnet-4-6", apiKey: "k", baseUrl: "" })).toBe("anthropic/claude-sonnet-4-6");
    expect(aiderModelArg({ provider: "gemini", model: "gemini-2.0-flash", apiKey: "k", baseUrl: "" })).toBe("gemini/gemini-2.0-flash");
  });
  it("passes OpenAI models bare", () => {
    expect(aiderModelArg({ provider: "openai", model: "gpt-4o", apiKey: "k", baseUrl: "" })).toBe("gpt-4o");
  });
  it("routes a local / ollama model through the openai/ prefix (OpenAI-compatible endpoint)", () => {
    expect(aiderModelArg({ provider: "local", model: "qwen3-coder", apiKey: "", baseUrl: "http://x/v1" })).toBe("openai/qwen3-coder");
    expect(aiderModelArg({ provider: "ollama", model: "llama3", apiKey: "", baseUrl: "http://x/v1" })).toBe("openai/llama3");
  });
  it("leaves a model that already carries a provider/ prefix untouched", () => {
    expect(aiderModelArg({ provider: "anthropic", model: "anthropic/claude-3-5-sonnet", apiKey: "k", baseUrl: "" })).toBe("anthropic/claude-3-5-sonnet");
  });
});

describe("aiderEnv (#1172)", () => {
  it("maps each hosted provider's key to the var Aider/litellm reads", () => {
    expect(aiderEnv({ provider: "anthropic", model: "m", apiKey: "ant", baseUrl: "" })).toEqual({ ANTHROPIC_API_KEY: "ant" });
    expect(aiderEnv({ provider: "openai", model: "m", apiKey: "oai", baseUrl: "" })).toEqual({ OPENAI_API_KEY: "oai" });
    expect(aiderEnv({ provider: "gemini", model: "m", apiKey: "gem", baseUrl: "" })).toEqual({ GEMINI_API_KEY: "gem" });
  });
  it("omits a hosted key when none is set", () => {
    expect(aiderEnv({ provider: "anthropic", model: "m", apiKey: "", baseUrl: "" })).toEqual({});
  });
  it("carries OPENAI_API_BASE + a placeholder key for a local / ollama endpoint", () => {
    const e = aiderEnv({ provider: "local", model: "m", apiKey: "", baseUrl: "http://localhost:11434/v1" });
    expect(e.OPENAI_API_BASE).toBe("http://localhost:11434/v1");
    expect(e.OPENAI_API_KEY).toBe("sk-local-none"); // non-empty so the client inits
  });
});

// The per-agent context cap, end to end: the Settings field → `$BSC_AGENT_NUM_CTX`.
//
// WHY THIS FILE EXISTS SEPARATELY. `llmConfig` is a record, and a record carries its own tests — but a
// carried test can only be written by `bsc graph tests harvest`, which pairs by COLOCATED FILE, and
// this module's file was retired long ago. So its carried test is frozen at whatever it was when the
// file last existed and cannot be extended in place (filed as `bsc request` 139's sibling, 138). The
// new assertions live here instead. If that gap is ever closed, fold these back onto the record.
//
// WHAT IS BEING PINNED. `build_provider` in `crates/llm` has honoured `$BSC_AGENT_NUM_CTX` since
// #1829, but NOTHING EVER SET IT — Settings → LLM provider → "Per-agent context cap" was an
// uncontrolled `<input defaultValue="64000">` bound to no store field. So the only escape hatch for a
// prompt that overflows its context window existed and was unreachable, and the cost of overflowing is
// not proportional: Ollama truncates an at-or-over-window prompt to HALF the window and keeps the
// tail, discarding the head — which is where `CLAUDE.md` sits.
//
// MEASURED on this repo before the fix: a 33,580-token prompt against `num_ctx` 32,768 came back as
//   `truncating input prompt limit=16386 prompt=33580 keep=4 new=16386`
// in the Ollama server log, while the client cheerfully reported "context=121084 chars". The client
// cannot see the loss, which is why it went unnoticed — so these tests guard the wiring, not a symptom.
import { describe, it, expect } from "vitest";
import {
  resolveLlmConfig, bscAgentEnv, parseNumCtx, DEFAULT_NUM_CTX,
  type LlmConfigSource,
} from "@/shared/lib/core/llmConfig";

const base: LlmConfigSource = {
  llmProvider: "ollama",
  llmModel: "qwen3.5:9b",
  claudeApiKey: "",
  openaiKey: "",
  geminiKey: "",
  localBaseUrl: "http://localhost:11434/v1",
  llmNumCtx: "",
};

describe("parseNumCtx — three states, and they do not collapse into two", () => {
  it("reads an empty field as UNSET, not as zero", () => {
    // Unset must stay unset: it means "use the runtime's packaged ceiling", so raising that ceiling
    // reaches every install rather than only the ones that never opened the field. Collapsing it to
    // 0 would instead tell the runtime to set no `num_ctx` at all — the opposite instruction.
    expect(parseNumCtx("")).toBeUndefined();
    expect(parseNumCtx("   ")).toBeUndefined();
  });

  it("keeps `0` as a real value — it MEANS 'do not set num_ctx'", () => {
    expect(parseNumCtx("0")).toBe(0);
  });

  it("reads a typed ceiling, tolerating surrounding whitespace", () => {
    expect(parseNumCtx("65536")).toBe(65536);
    expect(parseNumCtx("  32768 ")).toBe(32768);
  });

  it("treats garbage and negatives as unset rather than passing nonsense downstream", () => {
    expect(parseNumCtx("lots")).toBeUndefined();
    expect(parseNumCtx("-1")).toBeUndefined();
  });
});

describe("the cap reaches the runtime as $BSC_AGENT_NUM_CTX", () => {
  it("carries a typed cap all the way from the store field to the env var", () => {
    // The whole point of the slice: what the user types in Settings is what the runtime is told.
    const cfg = resolveLlmConfig({ ...base, llmNumCtx: "65536" });
    expect(cfg.numCtx).toBe(65536);
    expect(bscAgentEnv(cfg).BSC_AGENT_NUM_CTX).toBe("65536");
  });

  it("passes `0` through instead of dropping it", () => {
    // The subtle half. A truthy `if (cfg.numCtx)` would silently discard exactly this instruction
    // while looking correct — 0 and unset are DIFFERENT requests to the runtime.
    const cfg = resolveLlmConfig({ ...base, llmNumCtx: "0" });
    expect(bscAgentEnv(cfg).BSC_AGENT_NUM_CTX).toBe("0");
  });

  it("says NOTHING when the field is blank, so the runtime's own default applies", () => {
    const cfg = resolveLlmConfig({ ...base, llmNumCtx: "" });
    expect("BSC_AGENT_NUM_CTX" in bscAgentEnv(cfg)).toBe(false);
  });

  it("is absent for a source that predates the field entirely", () => {
    // `llmNumCtx` is OPTIONAL on LlmConfigSource on purpose: the interface is a structural subset so
    // the resolver stays unit-testable with a plain object, and adding a field must not invalidate
    // every existing caller's literal. Absent behaves exactly as blank.
    const { llmNumCtx: _omitted, ...withoutTheField } = base;
    expect("BSC_AGENT_NUM_CTX" in bscAgentEnv(resolveLlmConfig(withoutTheField))).toBe(false);
  });
});

describe("the packaged default", () => {
  it("is a real number the Settings placeholder can show", () => {
    // The old placeholder was the string "64000", which matched no default on either side of the
    // language boundary. This one comes from `@data/console/model-defaults.json`.
    expect(Number.isInteger(DEFAULT_NUM_CTX)).toBe(true);
    expect(DEFAULT_NUM_CTX).toBeGreaterThan(0);
  });

  it("is big enough for this app's OWN composed system prompt", () => {
    // Not an arbitrary number. The context this app composes for a worker — the CLAUDE.md chain +
    // CLAUDE.local.md + skills + the CLI inventory + the agent preamble + serialized tool schemas —
    // measured 33,580 tokens on the base-studio-code checkout. A default at or below that guarantees
    // the truncation this slice exists to remove, so the floor is a real constraint, not taste.
    expect(DEFAULT_NUM_CTX).toBeGreaterThan(33_580);
  });

  // The Rust side compiles its own copy of this number as `DEFAULT_NUM_CTX_CAP`, because the cap has
  // to apply when nothing sets the env var at all. `default_num_ctx_cap_matches_the_packaged_default`
  // in `crates/llm/src/ollama.rs` reads the same JSON and fails if the two diverge — that guard lives
  // there rather than here because only the Rust side can see its own constant.
});

import { describe, it, expect } from "vitest";
import { isLocalModelInstalled, pickInstalledLocalModel, DEFAULT_LOCAL_MODEL } from "@/shared/lib/core/llmConfig";

// #176: the packaged local default (qwen3-coder) is a GUESS — this machine's Ollama might not
// have it. These two pure helpers let a caller that DOES know the installed list (the Settings
// LLM provider card, after probing `ollama_models`) resolve against reality instead of blindly
// trusting the packaged name.
describe("isLocalModelInstalled (#176)", () => {
  it("matches an exact installed name", () => {
    expect(isLocalModelInstalled("qwen3.5:9b", ["qwen3.5:9b", "llama3.1:8b"])).toBe(true);
  });
  it("matches a bare name against a tagged install", () => {
    expect(isLocalModelInstalled("qwen3-coder", ["qwen3-coder:latest"])).toBe(true);
  });
  it("does not match a different tag of the same base model", () => {
    expect(isLocalModelInstalled("qwen3.5:99b", ["qwen3.5:9b"])).toBe(false);
  });
  it("is false against an empty or non-matching list", () => {
    expect(isLocalModelInstalled("qwen3-coder", [])).toBe(false);
    expect(isLocalModelInstalled("qwen3-coder", ["llama3.1:8b"])).toBe(false);
  });
});

describe("pickInstalledLocalModel (#176)", () => {
  it("prefers the packaged default when it (or its tagged form) is installed", () => {
    expect(pickInstalledLocalModel(DEFAULT_LOCAL_MODEL, ["qwen3-coder:latest", "llama3.1:8b"])).toBe("qwen3-coder:latest");
  });
  it("falls back to the first installed model when the preferred one is absent", () => {
    expect(pickInstalledLocalModel(DEFAULT_LOCAL_MODEL, ["qwen3.5:9b", "llama3.1:8b"])).toBe("qwen3.5:9b");
  });
  it("returns undefined when nothing is installed — the caller keeps the packaged default", () => {
    expect(pickInstalledLocalModel(DEFAULT_LOCAL_MODEL, [])).toBeUndefined();
  });
});

// The provider environment, captured from the LIVE TypeScript so the Rust mapping can be proved equal.
//
// Everything downstream of these two functions is Rust: `crates/bsc-agent/src/main.rs` reads
// `BSC_AGENT_PROVIDER`/`MODEL`/`API_KEY`, and `crates/llm` reads `BSC_AGENT_NUM_CTX` and clamps
// `num_ctx` by it (#1829). So the entire model-reaching configuration is consumed in Rust and was
// composed here.
//
// THE CASE THIS FIXTURE EXISTS FOR is `numCtx: 0`. The TypeScript tests `!== undefined`, deliberately
// NOT truthiness, because 0 MEANS "do not set num_ctx" — an instruction, not an absence. A truthy test
// drops exactly that instruction while looking correct. `build_provider` has honoured the variable
// since #1829 but nothing ever SET it, so the one escape hatch for a prompt that overflows its window
// existed and was unreachable.
//
//     UPDATE_FIXTURES=1 npx vitest run .bsc-records/shared/lib/core/llmConfig.3.test.ts
import { describe, it, expect } from "vitest";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { bscAgentEnv, aiderEnv, aiderModelArg } from "@/shared/lib/core/llmConfig";
import type { LlmConfig, LlmProvider } from "@/shared/lib/core/llmConfig";

const FIXTURE = join(process.cwd(), "src/shared/lib/core/providerEnv.fixtures.json");

const PROVIDERS: LlmProvider[] = ["anthropic", "openai", "gemini", "local", "ollama"];

const cfg = (over: Partial<LlmConfig> = {}): LlmConfig => ({
  provider: "anthropic", model: "opus-4.5", apiKey: "", baseUrl: "", numCtx: undefined, ...over,
});

type Case = { label: string; cfg: LlmConfig };

const SUBJECTS: Case[] = [
  ...PROVIDERS.map((p) => ({ label: `provider ${p}, keyed`, cfg: cfg({ provider: p, apiKey: "sk-secret" }) })),
  ...PROVIDERS.map((p) => ({ label: `provider ${p}, NO key`, cfg: cfg({ provider: p }) })),

  { label: "a local endpoint with a base URL", cfg: cfg({ provider: "ollama", model: "qwen2.5-coder", baseUrl: "http://box:11434/v1" }) },
  { label: "a local endpoint with NO base URL", cfg: cfg({ provider: "ollama", model: "qwen2.5-coder" }) },
  { label: "a local endpoint WITH a key too", cfg: cfg({ provider: "local", model: "llama3", baseUrl: "http://box:11434/v1", apiKey: "sk-x" }) },

  // THE numCtx SHAPES. `0` is an instruction; a truthy test would drop it.
  { label: "numCtx ABSENT — say nothing, let the runtime use its packaged ceiling", cfg: cfg({ numCtx: undefined }) },
  { label: "numCtx 0 — a real instruction meaning DO NOT set num_ctx", cfg: cfg({ numCtx: 0 }) },
  { label: "numCtx 1 — the smallest truthy value", cfg: cfg({ numCtx: 1 }) },
  { label: "numCtx 65536", cfg: cfg({ numCtx: 65536 }) },
  { label: "numCtx 0 on a local provider", cfg: cfg({ provider: "ollama", model: "q", baseUrl: "http://b:1/v1", numCtx: 0 }) },

  // Model-selector shapes.
  { label: "an already-namespaced model passes through", cfg: cfg({ provider: "anthropic", model: "vendor/some-model" }) },
  { label: "a model with surrounding whitespace", cfg: cfg({ provider: "openai", model: "  gpt-4o  " }) },
];

describe("providerEnv fixtures", () => {
  it("captures the bsc-agent env, the aider env and the model selector", () => {
    const cases = SUBJECTS.map((c) => ({
      label: c.label,
      config: c.cfg,
      bscAgent: bscAgentEnv(c.cfg),
      aider: aiderEnv(c.cfg),
      aiderModel: aiderModelArg(c.cfg),
    }));
    const next = { note: "GENERATED from @/shared/lib/core/llmConfig — do not hand-edit; see the .gen.test.ts", cases };

    if (process.env.UPDATE_FIXTURES) writeFileSync(FIXTURE, `${JSON.stringify(next, null, 2)}\n`);
    expect(existsSync(FIXTURE), `${FIXTURE} missing — run with UPDATE_FIXTURES=1`).toBe(true);
    expect(JSON.parse(readFileSync(FIXTURE, "utf8"))).toEqual(next);
  });

  it("numCtx 0 IS emitted and absent is NOT — the difference a truthy test destroys", () => {
    expect(bscAgentEnv(cfg({ numCtx: 0 })).BSC_AGENT_NUM_CTX, "0 means DO NOT set num_ctx").toBe("0");
    expect(bscAgentEnv(cfg({ numCtx: undefined })).BSC_AGENT_NUM_CTX, "absent says nothing").toBeUndefined();
    expect(bscAgentEnv(cfg({ numCtx: 65536 })).BSC_AGENT_NUM_CTX).toBe("65536");
  });

  it("an empty key or base URL emits NO variable rather than an empty one", () => {
    const e = bscAgentEnv(cfg({ apiKey: "", baseUrl: "" }));
    expect(e.BSC_AGENT_API_KEY).toBeUndefined();
    expect(e.BSC_AGENT_BASE_URL).toBeUndefined();
  });

  it("the local Aider path always supplies a NON-EMPTY key — the client will not init without one", () => {
    for (const p of ["local", "ollama"] as LlmProvider[]) {
      const e = aiderEnv(cfg({ provider: p, baseUrl: "http://b:1/v1" }));
      expect(e.OPENAI_API_KEY, `${p}: a keyless local server still needs a non-empty key`).toBeTruthy();
    }
  });
});
